<header class="page-header"><div><p class="eyebrow">Active campaign</p><h1>Prospects</h1><p>Campaign-specific relationships, research, and pipeline status.</p></div><a class="button" href="<?= $escape($newUrl) ?>">New prospect</a></header><nav class="tab-list"><a href="<?= $escape($activeUrl) ?>"<?= !$archived?' aria-current="page"':'' ?>>Active</a><a href="<?= $escape($archivedUrl) ?>"<?= $archived?' aria-current="page"':'' ?>>Archived</a></nav>
